  private readonly session = inject(Session);

  protected readonly grades = GRADES;
  protected readonly people = signal<Person[]>([]);
  protected readonly periods = signal<Period[]>([]);
  protected readonly pools = signal<Pool[]>([]);
  /** Per person id, in cents, their cuts across every pool they are a member of; a pool showing no cut adds nothing. */
  protected readonly personCuts = computed(() => {
    const cuts = new Map<number, number>();
    for (const pool of this.pools()) {
      for (const m of pool.members) {
        if (m.personId !== null && m.cut !== null) cuts.set(m.personId, (cuts.get(m.personId) ?? 0) + cents(m.cut));
      }
    }
    return cuts;
  });
  /** Per person id, their due-total for each period on the sheet, by period id. */
  protected readonly periodTotals = computed(
    () => new Map(this.people().map((p) => [p.id, personPeriodTotals(this.periods(), p)])),
  );
  protected readonly name = signal('');
  protected readonly grade = signal('A');
  /** The date an edit's grade applies from; blank: the sheet's today. */
  protected readonly gradeFrom = signal('');
  /** The person's own terms in days; blank: none. */

  /** Each person's patrons, each as their name and share, sorted by name and comma separated, and their
   *  backing: each patron's recent settled figure (see {@link Person.recentSettled}) times their share
   *  divided by 100, added up and rounded half to even (see {@link patronShares}). */
  protected readonly patronage = computed(() => {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    return new Map(
      this.people().map((p) => {
        const patrons = p.patrons.map((id) => byId.get(id)).filter((q): q is Person => q !== undefined);
        const shares = patronShares(patrons.length);
        const named = patrons.map((q, i) => ({ name: q.name, share: shares[i] }));
        const names = named
          .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
          .map((n) => `${n.name} ${(n.share / 100).toFixed(2)}`)
          .join(', ');
        // cents times hundredths of a percent: ten-thousandths of a cent.
        const backing = patrons.reduce((sum, q, i) => sum + cents(q.recentSettled) * shares[i], 0);
        return [p.id, { names, backing: (halfEven(backing, 10000) / 100).toFixed(2) }];
      }),
    );
  });

  /** Everyone's overdue claims counted up. */
  protected readonly overdueCount = computed(() => this.people().reduce((sum, p) => sum + p.overdueCount, 0));
  /** The person on the sheet with the signed-in user's name or alias, as names are compared; null when none. */
  protected readonly me = computed(() => {
    const user = this.session.user();
    if (user === null) return null;
    const key = nameKey(user);
    return this.people().find((p) => [p.name, ...(p.aliases ?? [])].some((n) => nameKey(n) === key)) ?? null;
  });
  /** Everyone's overdue-total added up, trimmed (see {@link trimmedSum}). */
  protected readonly overdueTotal = computed(() => (overdueTotalOf(this.people()) / 100).toFixed(2));
  /** The figures of each of the sheet's descendants (its children, theirs, and so on), as each shows them. */
  private readonly descendants = signal<SheetFigures[]>([]);
  /** The sheet's own live figures while it is shown as of a date; null while it is shown live (its people then). */
  private readonly live = signal<SheetFigures | null>(null);
  /**
   * The people counted, and the due- and overdue-totals added up, over the sheet and all its descendants, as
   * they stand live whatever date the sheet is shown as of.
   */
  protected readonly consolidated = computed(() => {
    const all = [this.live() ?? figuresOf(this.people()), ...this.descendants()];
    return {
      people: all.reduce((sum, f) => sum + f.people, 0),
      due: (all.reduce((sum, f) => sum + f.due, 0) / 100).toFixed(2),
      overdue: (all.reduce((sum, f) => sum + f.overdue, 0) / 100).toFixed(2),
    };
  });

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.people.set([]);
      this.descendants.set([]);
import { Component, computed, inject, input } from '@angular/core';
import type { PersonWithClaims } from '../claims/claims';
import { Period, periodDueTotals } from '../periods/periods';
import { VoidReasonList } from '../void-reasons/void-reasons';

const GRADES = ['A', 'B', 'C'];
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** Cents in an amount shown with two decimals ("12.50" is 1250). */
function cents(amount: string): number {
  return Math.round(Number(amount) * 100);
}

/** How many claims the people have in each status, in status order. */
export function statusCounts(people: PersonWithClaims[]): { status: string; count: number }[] {
  const claims = people.flatMap((p) => p.claims);
  return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
}

// The sheet's figures summed from the list: per grade, the people on it today (retired people left
// out), their due-totals added up (n/a skipped) and how many of them are active; per period, its due-total and its change from the period before it by start date (none for the earliest); per month any claim is dated in, the dues of
// its claims that count; per status, how many
// claims have it; per reason on the sheet's void reasons, how many VOID claims were voided with it.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-label="Summary">
      <h2>Summary</h2>
      <table>
        <caption>By grade</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">People</th><th scope="col">Due total</th><th scope="col">Active</th></tr>
        </thead>
        <tbody>
          @for (g of byGrade(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-active'">{{ g.active }}</td>
export class Summary {
  private readonly voidReasons = inject(VoidReasonList);

  readonly people = input.required<PersonWithClaims[]>();
  readonly periods = input.required<Period[]>();

  protected readonly byGrade = computed(() =>
    GRADES.map((grade) => {
      const on = this.people().filter((p) => !p.retired && p.grade === grade);
      const due = on.reduce((sum, p) => sum + (p.dueTotal === null ? 0 : cents(p.dueTotal)), 0);
      return { grade, count: on.length, dueTotal: (due / 100).toFixed(2), active: on.filter((p) => p.active).length };
    }),
  );

  protected readonly byPeriod = computed(() => {
    const totals = periodDueTotals(this.periods(), this.people());
    const previous = new Map<number, string>();
    const byStart = [...this.periods()].sort((a, b) => a.from.localeCompare(b.from));
    byStart.forEach((p, i) => {
      if (i > 0) previous.set(p.id, totals[byStart[i - 1].id]);
    });
    return this.periods().map((p) => {
      const before = previous.get(p.id);
      const change = before === undefined ? '' : ((cents(totals[p.id]) - cents(before)) / 100).toFixed(2);
      return { name: p.name, dueTotal: totals[p.id], change };
    });
  });

  /** Every month (yyyy-mm) any claim is dated in, earliest first, with the dues of its claims that count added up. */
  protected readonly byMonth = computed(() => {
    const totals = new Map<string, number>();
    for (const c of this.people().flatMap((p) => p.claims)) {
      const month = c.date.slice(0, 7);
      const due = c.counts && c.due !== null ? cents(c.due) : 0;
      totals.set(month, (totals.get(month) ?? 0) + due);
    }
    return [...totals.keys()].sort().map((month) => ({ month, dueTotal: ((totals.get(month) ?? 0) / 100).toFixed(2) }));
  });

  protected readonly byStatus = computed(() => statusCounts(this.people()));

  protected readonly byVoidReason = computed(() => {
    const voided = this.people().flatMap((p) => p.claims).filter((c) => c.status === 'VOID');
    return this.voidReasons.reasons().map((reason) => ({ reason, count: voided.filter((c) => c.voidReason === reason).length }));
  });
}

